update(sim){const active=sim.activeAbilities();if(this.layoutKey!==sim.definition.id+active.map(a=>a.id).join('|'))this.setDefinition({...sim.definition,abilities:active});for(const [id,button] of this.buttons){const a=sim.ability(id),remaining=sim.cooldowns.remaining(a.cooldownKey||id,sim.now),bonus=id===sim.definition.bonus?.id;button.hidden=bonus&&!sim.temporary.available(id,sim.now);if(button.hidden&&this.active?.id===id)this.release();const meterLocked=!!sim.match&&a.ultimate&&!sim.match.ultimateReady(sim);button.classList.toggle('unready',remaining>0||sim.player.dead||meterLocked||!!sim.match&&!sim.match.active);button.style.setProperty('--cool',`${remaining/a.cooldown*100||0}%`);button.querySelector('.cooldown').textContent=remaining>0?remaining.toFixed(1):meterLocked?Math.floor(sim.player.ultimateMeter)+'%':bonus?Math.ceil((sim.temporary.grants.get(id)?.expires||sim.now)-sim.now)+'s':'';}}
clear(){this.release();this.actions=[];this.keyboardBasic=null;this.pendingBasic=null;}
releaseBasic(a){return this.definition.id==='riven'&&a.basic;}
commitBasic(a,angle){this.actions.push({id:a.id,angle});this.pendingBasic=a.effect==='weaponSequence'&&this.sim?.weapons.next===0?{id:a.id,angle,submitted:false}:null;}
read(){const actions=this.actions.splice(0);if(this.pendingBasic&&actions.some(a=>a.id===this.pendingBasic.id))this.pendingBasic.submitted=true;return {actions,attackHeld:this.attackHeld};}
update(sim){this.sim=sim;const pending=this.pendingBasic;if(pending?.submitted){if(!this.input.enabled||sim.player.dead||sim.stance!=='reso'||sim.weapons.next!==1||sim.weapons.returning)this.pendingBasic=null;else if(sim.cooldowns.ready(sim.ability(pending.id).cooldownKey||pending.id,sim.now)){this.actions.push({id:pending.id,angle:pending.angle});this.pendingBasic=null;}}const active=sim.activeAbilities();if(this.layoutKey!==sim.definition.id+active.map(a=>a.id).join('|'))this.setDefinition({...sim.definition,abilities:active});for(const [id,button] of this.buttons){const a=sim.ability(id),remaining=sim.cooldowns.remaining(a.cooldownKey||id,sim.now),bonus=id===sim.definition.bonus?.id;button.hidden=bonus&&!sim.temporary.available(id,sim.now);if(button.hidden&&this.active?.id===id)this.release();const meterLocked=!!sim.match&&a.ultimate&&!sim.match.ultimateReady(sim);button.classList.toggle('unready',remaining>0||sim.player.dead||meterLocked||!!sim.match&&!sim.match.active);button.style.setProperty('--cool',`${remaining/a.cooldown*100||0}%`);button.querySelector('.cooldown').textContent=remaining>0?remaining.toFixed(1):meterLocked?Math.floor(sim.player.ultimateMeter)+'%':bonus?Math.ceil((sim.temporary.grants.get(id)?.expires||sim.now)-sim.now)+'s':'';}}

